/**
 * Contract C3/C8, on `src/api/schema.d.ts` — generated by `make types` from the
 * real pydantic models and held to the tree by `make lint-generated`.
 *
 * Every vocabulary below is derived from the generated model rather than
 * restated, because the backend already declares them as `Literal`s. `RunKind`,
 * `BlockType` and `ItemState` were three places where a hand-written copy could
 * disagree with the server about what values exist, and now they cannot.
 */

import type { components } from '@/api/schema'

type Schemas = components['schemas']

export type BriefBlock = Schemas['BriefBlock']
export type BlockType = BriefBlock['type']

/** Runs concatenate back to the block's plain text, exactly. */
export type TextRun = Schemas['TextRun']
export type RunKind = NonNullable<TextRun['k']>

/** One story. `summary` is what the article reports; `why` is the judgement.
 *  They are separate fields, not separate paragraphs of one blob — that
 *  separation is the format. Both are annotated identically. */
export type BriefItem = Schemas['BriefItem']
export type ItemState = BriefItem['state']

/** `blocks` holds narrative blocks. Empty for every brief in the item format;
 *  retained so the pre-item archive still renders. */
export type BriefSection = Schemas['BriefSection']

export type BriefTop = Schemas['BriefTop']
export type Freshness = Schemas['Freshness']
export type BriefSource = Schemas['BriefSource']
export type Brief = Schemas['Brief']

// ── cards ────────────────────────────────────────────────────────────

/** One row of the archive list from `GET /briefs`.
 *
 *  `generated_at` is what tells two briefs on the same date apart in the
 *  archive. Nullable: rows written before brief ids became unique per
 *  generation are still one-per-day, but the column has always been set. */
export type BriefSummary = Schemas['BriefSummary']

export type BriefList = Schemas['BriefList']

/** `GET /briefs/search`. `where` says which part of the brief matched, because
 *  it changes what the reader should do with the hit: a `title` match means the
 *  brief is about the thing, a `body` match means one item mentions it. */
export type BriefSearchMatch = Schemas['BriefSearchMatch']
export type BriefSearchHit = Schemas['BriefSearchHit']
export type BriefSearchResults = Schemas['BriefSearchResults']

export type Signal = Schemas['Signal']
export type MiniGraphNeighbor = Schemas['MiniGraphNeighbor']
export type MiniGraph = Schemas['MiniGraph']
export type Grounding = Schemas['Grounding']
export type GlossaryAlternative = Schemas['GlossaryAlternative']

/**
 * `definition_sources` carries the articles a tier-2 entity definition rests
 * on. Those are WRITTEN from several evidence sentences rather than quoted from
 * one, so they have no quote and are rendered as "drawn from N articles", never
 * as a blockquote — a synthesis shown as a quotation is what invariant 3 exists
 * to prevent.
 *
 * On an undefined card, `last_attempt_at` being null means no web lookup has
 * ever run for the surface; set means one ran and grounded nothing — which is
 * why the card offers "Try again" rather than "Look this up", and links to what
 * it tried.
 */
export type Card = Schemas['Card']

export type CardBatchResponse = Schemas['CardBatchResponse']
